import basalt.Basalt;
import basalt.core.BC;
import basalt.nn.Activation;
import basalt.torch.AdamW;
import basalt.torch.Loss;
import basalt.torch.Optimizer;
import basalt.torch.Sequential;
import basalt.torch.Tensor; try (Basalt jsl = Basalt.create()) { // start() 产生空流水线，输入与输出都钉在 BC Sequential<BC, BC> model = Sequential.<BC>start() .add(basalt.linear(8, 16)) .add(basalt.activation(Activation.RELU)) .add(basalt.linear(16, 4)); Tensor features = basalt.randn(32, 8); Tensor targets = basalt.zeros(32, 4); Loss criterion = basalt.mse(); Optimizer optimizer = new AdamW(model.parameters(), 0.01f); for (int step = 0; step < 5; step++) { Tensor loss = criterion.loss(model.forward(features), targets); loss.backward(); // 1. 反向：梯度累积到参数 optimizer.step(); // 2. 更新：消费当前梯度 optimizer.zeroGrad(); // 3. 清零：为下一批准备 basalt.clearGraph(); // 4. 清图：丢弃本步节点与中间张量 }
}

import basalt.Basalt;
import basalt.torch.Tensor; try (Basalt jsl = Basalt.create()) { Tensor features = basalt.randn(4, 3); // 形状 [4, 3]，不求导 Tensor weight = basalt.parameter(3, 1); // 可训练参数，零初始化 Tensor loss = features.matMul(weight) // [4, 3] x [3, 1] -> [4, 1] .mse(basalt.zeros(4, 1)); // 标量损失，形状 [1] loss.backward(); // 梯度累加到 weight float[] gradient = weight.grad(); // 复制出梯度 weight.sgd(0.1f, 0.0f); // weight -= lr * grad weight.zeroGrad(); // 清梯度 basalt.clearGraph(); // 清图，避免节点累积
}
